class Solution:
    def isPossibleToSplit(self, nums: list[int]) -> bool:
        from collections import Counter
        count = Counter(nums)
        # If any number appears more than 2 times, we can't split into two sets of unique elements
        for v in count.values():
            if v > 2:
                return False
        return True
```

